// Title: Convert CSV to PDF with Aspose.Cells for .NET (C#) and understand PDF creation date limitation
// Common Searches: how to use Aspose.Cells in C# to convert a CSV file to PDF | Aspose.Cells C# example for saving workbook as PDF | set custom creation date in PDF generated by Aspose.Cells .NET | why Aspose.Cells cannot modify PDF metadata like creation time | load CSV into Aspose.Cells workbook with LoadOptions in C#
// Tags: Aspose.Cells PDF generation from CSV | PdfSaveOptions usage in Aspose.Cells | LoadOptions for CSV files in Aspose.Cells | PDF creation date metadata limitation in Aspose.Cells | custom PDF metadata handling .NET

using System;
using System.IO;
using Aspose.Cells;

// The sample loads a CSV file into an Aspose.Cells Workbook using LoadOptions with LoadFormat.Csv, then saves it as a PDF via PdfSaveOptions. Although a historical DateTime is defined, Aspose.Cells does not provide an API to embed a custom creation timestamp into the resulting PDF, highlighting a limitation in PDF metadata manipulation.
class CsvToPdfConverter
{
    static void Main()
    {
        // Define file paths
        string csvPath = "input.csv";
        string pdfPath = "output.pdf";

        // Define the historical creation date (not applied due to library limitation)
        DateTime historicalCreationDate = new DateTime(1995, 5, 23, 10, 30, 0);

        try
        {
            // Verify CSV file exists
            if (!File.Exists(csvPath))
                throw new FileNotFoundException($"CSV file not found: {csvPath}");

            // Load the CSV file into a Workbook
            LoadOptions loadOptions = new LoadOptions(LoadFormat.Csv);
            Workbook workbook = new Workbook(csvPath, loadOptions);

            // Save the workbook as PDF
            PdfSaveOptions pdfSaveOptions = new PdfSaveOptions();
            // Note: Aspose.Cells does not provide direct PDF metadata manipulation.
            workbook.Save(pdfPath, pdfSaveOptions);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }
}
